import XRender

/// Renderer-neutral texture updates generated by an XAppSession's font book.
public enum XUIFontTextureUpdate: Sendable {
    case create(id: TextureID, rgba: [UInt8], width: Int, height: Int)
    case update(id: TextureID, rgba: [UInt8], y: Int, width: Int, height: Int)

    public func apply(to renderer: any XTextureRenderer) {
        switch self {
        case let .create(id, rgba, width, height):
            renderer.registerTexture(id, rgba: rgba, width: width, height: height)
        case let .update(id, rgba, y, width, height):
            renderer.updateTexture(id, rgba: rgba, y: y, width: width, height: height)
        }
    }
}
